// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceRappOperationVault {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceRappOperationVault = UniffiVTableCallbackInterfaceRappOperationVault(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeRappOperationVault.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface RappOperationVault: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeRappOperationVault.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface RappOperationVault: handle missing in uniffiClone")
            }
        },
        persistRequester: { (
            uniffiHandle: UInt64,
            pairId: RustBuffer,
            operationId: RustBuffer,
            record: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterTypeRappOperationVault.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try uniffiObj.persistRequester(
                     pairId: try FfiConverterData.lift(pairId),
                     operationId: try FfiConverterData.lift(operationId),
                     record: try FfiConverterData.lift(record)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCallWithError(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn,
                lowerError: FfiConverterTypeRappVaultError_lower
