/**
 * Deliberately coarse binding failure. Protocol internals and secrets never
 * become UI strings or foreign-language log material.
 */
public 
enum RappBindingError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * Caller-provided bytes or registry values were invalid.
     */
    case InvalidInput
    /**
     * Method was not legal in the current protocol phase.
     */
    case WrongPhase
    /**
     * Authenticated protocol or cryptographic processing failed.
     */
    case ProtocolFailure
    /**
     * Local synchronization state was poisoned and cannot be reused.
     */
    case LocalStateFailure
    /**
     * Requested active pair record was not present in device-only storage.
     */
    case PairNotFound

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension RappBindingError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeRappBindingError: FfiConverterRustBuffer {
    typealias SwiftType = RappBindingError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> RappBindingError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidInput
        case 2: return .WrongPhase
        case 3: return .ProtocolFailure
        case 4: return .LocalStateFailure
        case 5: return .PairNotFound

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: RappBindingError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .InvalidInput:
            writeInt(&buf, Int32(1))
        
        
        case .WrongPhase:
            writeInt(&buf, Int32(2))
        
        
        case .ProtocolFailure:
            writeInt(&buf, Int32(3))
        
        
        case .LocalStateFailure:
            writeInt(&buf, Int32(4))
        
        
        case .PairNotFound:
            writeInt(&buf, Int32(5))
        
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeRappBindingError_lift(_ buf: RustBuffer) throws -> RappBindingError {
    return try FfiConverterTypeRappBindingError.lift(buf)
}

